// src/pages/dashboard/hooks/useAdminDashboard.js
import { useState, useEffect, useCallback } from 'react';
import { useAuthContext } from '../../../../viewmodels/hooks/useAuthContext';
import { useAdmin } from '../../../../viewmodels/hooks/UseAdmin';
import { useCourseContext } from '../../../../viewmodels/context/CourContext';
// Firebase v8 syntax (compat)
import firebase from 'firebase/compat/app';
import 'firebase/compat/firestore';
import { db } from '../../../../firebase/config'; // Votre configuration

export const useAdminDashboard = () => {
  const { user } = useAuthContext();
  const { isAdmin } = useAdmin();
  const { courses, addCourse, deleteCourse, updateCourse } = useCourseContext();
  
  // États pour les données dynamiques
  const [quizzes, setQuizzes] = useState([]);
  const [users, setUsers] = useState([]);
  const [payments, setPayments] = useState([]);
  const [activeTab, setActiveTab] = useState('overview');
  const [showNewCourseForm, setShowNewCourseForm] = useState(false);
  const [lastUpdated, setLastUpdated] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  
  const [newCourse, setNewCourse] = useState({
    title: '',
    category: '',
    instructor: '',
    originalPrice: '',
    price: '',
    description: '',
    level: 'Intermédiaire',
    duration: '10h 00min',
    image: '/images/default-course.jpg',
    discountPercentage: 0,
    hasPromotion: false,
    status: 'draft'
  });

  // Mettre à jour lastUpdated quand les données changent
  useEffect(() => {
    if (courses.length > 0 || quizzes.length > 0 || users.length > 0 || payments.length > 0) {
      setLastUpdated(new Date().toISOString());
    }
  }, [courses, quizzes, users, payments]);

  // Charger toutes les données dynamiques depuis Firestore
  useEffect(() => {
    if (!isAdmin) return;

    let unsubscribeQuizzes = () => {};
    let unsubscribeUsers = () => {};
    let unsubscribePayments = () => {};

    const loadAllData = async () => {
      setIsLoading(true);
      try {
        // Charger les quizzes avec Firebase v8 syntax
        unsubscribeQuizzes = db.collection('quizzes')
          .orderBy('updatedAt', 'desc')
          .onSnapshot((snapshot) => {
            const quizzesData = snapshot.docs.map(doc => ({
              id: doc.id,
              ...doc.data(),
              createdAt: doc.data().createdAt?.toDate ? doc.data().createdAt.toDate() : null,
              updatedAt: doc.data().updatedAt?.toDate ? doc.data().updatedAt.toDate() : null
            }));
            setQuizzes(quizzesData);
          });

        // Charger les utilisateurs
        unsubscribeUsers = db.collection('users')
          .orderBy('createdAt', 'desc')
          .onSnapshot((snapshot) => {
            const usersData = snapshot.docs.map(doc => ({
              id: doc.id,
              ...doc.data(),
              createdAt: doc.data().createdAt?.toDate ? doc.data().createdAt.toDate() : null,
              lastLogin: doc.data().lastLogin?.toDate ? doc.data().lastLogin.toDate() : null
            }));
            setUsers(usersData);
          });

        // Charger les paiements
        unsubscribePayments = db.collection('payments')
          .orderBy('paymentDate', 'desc')
          .onSnapshot((snapshot) => {
            const paymentsData = snapshot.docs.map(doc => ({
              id: doc.id,
              ...doc.data(),
              paymentDate: doc.data().paymentDate?.toDate ? doc.data().paymentDate.toDate() : null
            }));
            setPayments(paymentsData);
          });

        setIsLoading(false);

      } catch (error) {
        console.error('Erreur lors du chargement des données:', error);
        setIsLoading(false);
      }
    };

    loadAllData();

    // Nettoyer les écouteurs quand le composant est démonté
    return () => {
      if (unsubscribeQuizzes) unsubscribeQuizzes();
      if (unsubscribeUsers) unsubscribeUsers();
      if (unsubscribePayments) unsubscribePayments();
    };
  }, [isAdmin]);

  // Calculer les revenus pour chaque cours basé sur les paiements
  const calculateCourseRevenues = useCallback(() => {
    if (!payments.length || !courses.length) return {};

    const courseRevenues = {};
    
    payments.forEach(payment => {
      if (payment.status === 'completed' && payment.courseId) {
        if (!courseRevenues[payment.courseId]) {
          courseRevenues[payment.courseId] = 0;
        }
        courseRevenues[payment.courseId] += payment.amount || 0;
      }
    });

    return courseRevenues;
  }, [payments, courses]);

  // Calculer le nombre d'étudiants par cours
  const calculateCourseEnrollments = useCallback(() => {
    if (!users.length) return {};

    const courseEnrollments = {};
    
    users.forEach(user => {
      if (user.enrolledCourses && Array.isArray(user.enrolledCourses)) {
        user.enrolledCourses.forEach(courseId => {
          if (!courseEnrollments[courseId]) {
            courseEnrollments[courseId] = 0;
          }
          courseEnrollments[courseId]++;
        });
      }
    });

    return courseEnrollments;
  }, [users]);

  // Mettre à jour les cours avec les données dynamiques
  const getEnhancedCourses = useCallback(() => {
    if (!courses.length) return [];
    
    const courseRevenues = calculateCourseRevenues();
    const courseEnrollments = calculateCourseEnrollments();
    
    return courses.map(course => ({
      ...course,
      revenue: courseRevenues[course.id] || 0,
      enrollmentCount: courseEnrollments[course.id] || 0,
      updatedAt: course.updatedAt || course.createdAt || new Date().toISOString()
    }));
  }, [courses, calculateCourseRevenues, calculateCourseEnrollments]);

  // Calculer les statistiques globales
  const calculateStats = useCallback(() => {
    const enhancedCourses = getEnhancedCourses();
    
    const totalRevenue = enhancedCourses.reduce((sum, course) => sum + (course.revenue || 0), 0);
    
    const currentMonth = new Date().getMonth();
    const currentYear = new Date().getFullYear();
    
    const monthlyRevenue = payments.reduce((sum, payment) => {
      if (payment.status === 'completed' && payment.paymentDate) {
        const paymentDate = payment.paymentDate;
        if (paymentDate.getMonth() === currentMonth && 
            paymentDate.getFullYear() === currentYear) {
          return sum + (payment.amount || 0);
        }
      }
      return sum;
    }, 0);

    const totalStudents = enhancedCourses.reduce((sum, course) => 
      sum + (course.enrollmentCount || 0), 0
    );
    
    const activeQuizzes = quizzes.filter(quiz => quiz.isActive !== false).length;
    
    // Calculer la croissance mensuelle
    const previousMonthRevenue = payments.reduce((sum, payment) => {
      if (payment.status === 'completed' && payment.paymentDate) {
        const paymentDate = payment.paymentDate;
        const prevMonth = currentMonth === 0 ? 11 : currentMonth - 1;
        const prevYear = currentMonth === 0 ? currentYear - 1 : currentYear;
        
        if (paymentDate.getMonth() === prevMonth && 
            paymentDate.getFullYear() === prevYear) {
          return sum + (payment.amount || 0);
        }
      }
      return sum;
    }, 0);

    const monthlyGrowth = previousMonthRevenue > 0 ? 
      ((monthlyRevenue - previousMonthRevenue) / previousMonthRevenue * 100).toFixed(1) : 0;

    return {
      totalRevenue,
      monthlyRevenue,
      totalStudents,
      totalCourses: enhancedCourses.length,
      totalQuizzes: quizzes.length,
      activeQuizzes,
      totalUsers: users.length,
      totalPayments: payments.filter(p => p.status === 'completed').length,
      monthlyGrowth,
      conversionRate: totalStudents > 0 ? 
        ((totalStudents / (users.length * 4)) * 100).toFixed(1) : 0
    };
  }, [courses, quizzes, users, payments, getEnhancedCourses]);

  const defaultImages = [
    { url: '/images/react.jpg', label: 'React' },
    { url: '/images/figma.webp', label: 'Figma' },
    { url: '/images/marketing-digital.jpg', label: 'Marketing' },
    { url: '/images/python.jpeg', label: 'Python' },
    { url: '/images/adobe.jpg', label: 'Adobe' },
    { url: '/images/agile.jpeg', label: 'Agile' },
    { url: '/images/ai.jpeg', label: 'Intelligence Artificielle' }, 
    { url: '/images/cour.png', label: 'Cours Général' },
    { url: '/images/default-course.jpg', label: 'Défaut' }
  ];

  const calculateDiscountPercentage = (originalPrice, promoPrice) => {
    const original = parseFloat(originalPrice);
    const promo = parseFloat(promoPrice);
    
    if (!original || !promo || original <= 0 || promo <= 0) {
      return 0;
    }
    
    if (promo >= original) {
      return 0;
    }
    
    const discount = ((original - promo) / original) * 100;
    return Math.round(discount);
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    
    setNewCourse(prev => {
      const updatedCourse = {
        ...prev,
        [name]: value
      };
      
      if (name === 'originalPrice' || name === 'price') {
        const originalPrice = name === 'originalPrice' ? value : prev.originalPrice;
        const promoPrice = name === 'price' ? value : prev.price;
        
        if (originalPrice && promoPrice) {
          const original = parseFloat(originalPrice);
          const promo = parseFloat(promoPrice);
          
          if (promo >= original) {
            updatedCourse.discountPercentage = 0;
            updatedCourse.hasPromotion = false;
          } else {
            const discountPercentage = calculateDiscountPercentage(original, promo);
            updatedCourse.discountPercentage = discountPercentage;
            updatedCourse.hasPromotion = discountPercentage > 0;
          }
        } else {
          updatedCourse.discountPercentage = 0;
          updatedCourse.hasPromotion = false;
        }
      }
      
      return updatedCourse;
    });
  };

  const handleImageUrlChange = (e) => {
    const { value } = e.target;
    setNewCourse(prev => ({
      ...prev,
      image: value || '/images/default-course.jpg'
    }));
  };

  const handleSelectDefaultImage = (imageUrl) => {
    setNewCourse(prev => ({
      ...prev,
      image: imageUrl
    }));
  };

  const handleSubmitCourse = (e) => {
    e.preventDefault();
    
    if (!newCourse.title || !newCourse.category || !newCourse.instructor || !newCourse.originalPrice) {
      alert('❌ Veuillez remplir tous les champs obligatoires');
      return;
    }
    
    const originalPrice = parseFloat(newCourse.originalPrice);
    const promoPrice = parseFloat(newCourse.price) || originalPrice;
    
    if (promoPrice > originalPrice) {
      alert('❌ Le prix promotionnel ne peut pas être supérieur au prix original');
      return;
    }
    
    if (originalPrice <= 0) {
      alert('❌ Le prix original doit être supérieur à 0');
      return;
    }

    const courseData = {
      title: newCourse.title,
      category: newCourse.category,
      instructor: newCourse.instructor,
      price: promoPrice,
      originalPrice: newCourse.hasPromotion ? originalPrice : null,
      description: newCourse.description,
      level: newCourse.level,
      duration: newCourse.duration,
      image: newCourse.image,
      discountPercentage: newCourse.discountPercentage,
      status: newCourse.status,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      // Ajouter des champs pour les statistiques
      enrollmentCount: 0,
      revenue: 0
    };

    try {
      addCourse(courseData);
      
      setNewCourse({
        title: '',
        category: '',
        instructor: '',
        originalPrice: '',
        price: '',
        description: '',
        level: 'Intermédiaire',
        duration: '10h 00min',
        image: '/images/default-course.jpg',
        discountPercentage: 0,
        hasPromotion: false,
        status: 'draft'
      });
      
      setShowNewCourseForm(false);
      alert('✅ Cours créé avec succès !');
      
    } catch (error) {
      console.error('❌ Erreur lors de la création du cours:', error);
      alert('❌ Erreur lors de la création du cours');
    }
  };

  const handleUpdateCourse = useCallback((courseId, courseData) => {
    try {
      const updatedData = {
        ...courseData,
        updatedAt: new Date().toISOString()
      };
      
      if (updateCourse) {
        updateCourse(courseId, updatedData);
      }
    } catch (error) {
      console.error('❌ Erreur lors de la mise à jour du cours:', error);
      alert('❌ Erreur lors de la mise à jour du cours');
    }
  }, [updateCourse]);

  const handleUpdateQuiz = useCallback((quizId, quizData) => {
    try {
      const updatedData = {
        ...quizData,
        updatedAt: new Date().toISOString()
      };
      
      // À implémenter: fonction pour mettre à jour les quizzes
      console.log('Quiz updated:', quizId, updatedData);
      
    } catch (error) {
      console.error('❌ Erreur lors de la mise à jour du quiz:', error);
      alert('❌ Erreur lors de la mise à jour du quiz');
    }
  }, []);

  const handleDeleteCourse = (courseId) => {
    if (window.confirm('Êtes-vous sûr de vouloir supprimer ce cours ?')) {
      deleteCourse(courseId);
      alert('✅ Cours supprimé avec succès !');
    }
  };

  const handleNewCourseClick = () => {
    setShowNewCourseForm(true);
  };

  const handleCloseModal = () => {
    setShowNewCourseForm(false);
    setNewCourse({
      title: '',
      category: '',
      instructor: '',
      originalPrice: '',
      price: '',
      description: '',
      level: 'Intermédiaire',
      duration: '10h 00min',
      image: '/images/default-course.jpg',
      discountPercentage: 0,
      hasPromotion: false,
      status: 'draft'
    });
  };

  // Fonction pour rafraîchir manuellement les données
  const refreshData = async () => {
    setIsLoading(true);
    try {
      // Recharger les données
      setLastUpdated(new Date().toISOString());
      setTimeout(() => setIsLoading(false), 500);
    } catch (error) {
      console.error('Erreur lors du rafraîchissement:', error);
      setIsLoading(false);
    }
  };

  return {
    user,
    isAdmin,
    courses: getEnhancedCourses(), // Retourner les cours enrichis
    quizzes,
    users,
    payments,
    activeTab,
    setActiveTab,
    showNewCourseForm,
    newCourse,
    defaultImages,
    lastUpdated,
    isLoading,
    stats: calculateStats(), // Retourner les statistiques calculées
    handleInputChange,
    handleImageUrlChange,
    handleSelectDefaultImage,
    handleSubmitCourse,
    handleDeleteCourse,
    handleUpdateCourse,
    handleUpdateQuiz,
    handleNewCourseClick,
    handleCloseModal,
    refreshData 
  };
};
